import sys

def main():
    data = sys.stdin.buffer.read().split(b'\n', 1)
    if len(data) < 2:
        return
    k = int(data[0])
    text = data[1].decode().strip()

    # Build tokens: each token is a piece that must stay together on a line.
    # A word with hyphens is split after each hyphen (hyphen stays with prefix).
    # Spaces are attached to the preceding token.
    tokens = []
    i = 0
    n = len(text)
    while i < n:
        j = i
        while j < n and text[j] != ' ':
            j += 1
        word = text[i:j]
        # split word at hyphens, keeping hyphen at end of each piece
        start = 0
        for p in range(len(word)):
            if word[p] == '-':
                tokens.append(word[start:p+1])
                start = p + 1
        tokens.append(word[start:])
        # attach space to last piece of this word if there is a following word
        if j < n:
            tokens[-1] += ' '
        i = j + 1

    # Binary search minimal width
    def feasible(width):
        lines = 1
        cur = 0
        for t in tokens:
            L = len(t)
            if L > width:
                return False
            if cur == 0:
                cur = L
            elif cur + L <= width:
                cur += L
            else:
                lines += 1
                if lines > k:
                    return False
                cur = L
        return lines <= k

    lo = 1
    hi = len(text)
    while lo < hi:
        mid = (lo + hi) // 2
        if feasible(mid):
            hi = mid
        else:
            lo = mid + 1
    print(lo)

